<template>
  <section class="app-case-reference report-reference">
    <div class="report-metrics"><article v-for="item in metrics" :key="item.label" class="app-case-metric" :class="item.tone"><span class="app-case-metric-icon"><component :is="item.icon" /></span><div><span>{{item.label}}</span><strong>{{item.value}}</strong><small>{{item.note}}</small></div></article></div>
    <a-alert v-if="error" type="error">执行报告加载失败，请刷新重试。<template #action><a-button size="mini" @click="emit('refresh')">重试</a-button></template></a-alert>
    <div class="report-workspace">
      <main class="report-main">
        <div class="report-charts">
          <section class="report-chart-panel"><header><h3>执行结果分布</h3><span>当前项目全部执行</span></header><div class="report-distribution"><div class="report-donut" :style="{background:donut}" role="img" :aria-label="`总执行 ${stats.total}，通过 ${stats.passed}，失败 ${stats.failed}，异常 ${stats.error}，其他 ${stats.other}`"><div><strong>{{stats.total.toLocaleString()}}</strong><span>执行次数</span></div></div><ul><li v-for="item in distribution" :key="item.label"><i :style="{background:item.color}"/><span>{{item.label}}</span><b>{{item.value}}</b><small>{{stats.total?`${(item.value/stats.total*100).toFixed(1)}%`:'—'}}</small></li></ul></div></section>
          <section class="report-chart-panel report-trend"><header><h3>近 7 天通过率趋势</h3><span :class="latestRate===null?'muted':latestRate===100?'passed-rate':'failed-rate'">{{rateText(latestRate)}}</span></header><svg viewBox="0 0 440 180" role="img" :aria-label="trendDescription"><g v-for="tick in [0,25,50,75,100]" :key="tick"><path :d="`M42 ${142-tick*1.1}H426`" stroke="var(--theme-border)" stroke-dasharray="3 4"/><text x="2" :y="146-tick*1.1">{{tick}}%</text></g><polyline v-for="(segment,index) in segments" :key="index" :points="segment" fill="none" stroke="#008f83" stroke-width="2.5"/><g v-for="(day,index) in stats.days" :key="day.day"><text :x="48+index*62" y="169" text-anchor="middle">{{day.day.slice(5)}}</text><circle v-if="day.rate!==null" :cx="48+index*62" :cy="142-day.rate*1.1" r="3.5" fill="white" :stroke="day.rate===100?'#16a34a':'#dc2626'" stroke-width="2"><title>{{day.day}}：{{rateText(day.rate)}}（{{day.passed}}/{{day.total}}）</title></circle></g></svg><p>按本地日期、已得出通过／失败／异常结论的执行次数统计；无数据不连线。</p></section>
        </div>
        <section class="app-case-list report-list" aria-label="执行报告列表">
          <div class="app-case-toolbar report-toolbar"><a-input v-model="search" allow-clear placeholder="搜索报告名称、执行 / 任务 ID 或套件" :input-attrs="{'aria-label':'搜索执行报告'}"><template #prefix><icon-search /></template></a-input><a-select v-model="source" aria-label="筛选报告来源"><a-option value="">执行来源 · 全部</a-option><a-option v-for="mode in sourceOptions" :key="mode" :value="mode">{{sourceLabel(mode)}}</a-option></a-select><a-select v-model="status" aria-label="筛选报告结果"><a-option value="">执行结果 · 全部</a-option><a-option v-for="item in stateOptions" :key="item.value" :value="item.value">{{item.label}}</a-option></a-select><a-range-picker v-model="dates" class="report-date-range" value-format="YYYY-MM-DD" format="YYYY-MM-DD" :allow-clear="true" :placeholder="['开始日期','结束日期']" aria-label="筛选报告日期" /></div>
          <div class="report-list-actions"><span>每条记录对应一次用例执行；通过率按实际步骤数计算。</span><a-space wrap><a-button aria-label="重置报告筛选" @click="reset"><icon-refresh /> 重置</a-button><a-button :loading="loading" aria-label="刷新执行报告" @click="emit('refresh')"><icon-refresh /> 刷新</a-button><a-button @click="emit('suites')"><icon-layers /> 套件概览</a-button><a-button :disabled="!filtered.length||error||loading" @click="exportRows(filtered)"><icon-download /> 导出摘要</a-button></a-space></div>
          <div v-if="selectedKeys.length" class="app-case-selection">已选择 {{selectedKeys.length}} 条<a-button type="text" size="mini" :disabled="error||loading" @click="exportRows(filtered.filter(record=>selectedKeys.includes(record.id)))">导出所选摘要</a-button><a-button type="text" size="mini" @click="selectedKeys=[]">清空选择</a-button></div>
          <a-table class="app-case-table report-table" :data="pageRecords" row-key="id" :bordered="false" :pagination="false" :loading="loading" :scroll="{x:1010}" :row-selection="{type:'checkbox',showCheckedAll:true}" v-model:selected-keys="selectedKeys"><template #columns>
            <a-table-column title="报告 ID" :width="105"><template #cell="{record}"><button class="report-name" @click="select(record)">{{executionCode(record)}}</button></template></a-table-column>
            <a-table-column title="报告名称 / 关联套件" :width="210"><template #cell="{record}"><button class="report-name" :class="{'report-selected-name':selected?.id===record.id}" :title="reportName(record)" @click="select(record)">{{reportName(record)}}</button><small class="report-muted" :title="reportSuite(record,suites)">{{reportSuite(record,suites)}}</small></template></a-table-column>
            <a-table-column title="执行结论" :width="100"><template #cell="{record}"><a-tag :color="reportStatus(record).color">{{reportStatus(record).label}}</a-tag></template></a-table-column>
            <a-table-column title="步骤通过率" :width="100"><template #cell="{record}"><strong :class="reportRate(record)===null?'muted':reportRate(record)===100?'passed-rate':'failed-rate'">{{rateText(reportRate(record))}}</strong></template></a-table-column>
            <a-table-column title="步骤数" :width="70"><template #cell="{record}">{{record.total_steps??'—'}}</template></a-table-column>
            <a-table-column title="执行时长" :width="95"><template #cell="{record}">{{clockDuration(record.duration)}}</template></a-table-column>
            <a-table-column title="执行时间" :width="155"><template #cell="{record}">{{formatTime(record)}}</template></a-table-column>
            <a-table-column title="操作" :width="100" fixed="right"><template #cell="{record}"><div class="app-case-row-actions"><a-button type="text" :aria-label="`完整报告 ${record.id}`" :disabled="error||!reportAvailable(record)" @click="emit('report',record)"><icon-file /></a-button><a-button type="text" :aria-label="`报告摘要 ${record.id}`" @click="select(record)"><icon-bar-chart /></a-button><a-dropdown trigger="click"><a-button type="text" :aria-label="`更多报告 ${record.id}`"><icon-more /></a-button><template #content><a-doption @click="emit('detail',record.id)">日志与执行证据</a-doption><a-doption :disabled="!record.test_suite_id" @click="emit('suite',record.test_suite_id)">查看关联套件</a-doption><a-doption @click="exportRows([record])">导出此份摘要</a-doption></template></a-dropdown></div></template></a-table-column>
          </template><template #empty><a-empty :description="executions.length?'没有符合条件的执行报告':'暂无执行记录，运行测试后查看报告'" /></template></a-table>
          <footer class="app-case-pagination"><span>共 {{filtered.length}} 条执行</span><a-pagination v-model:current="current" v-model:page-size="pageSize" :total="filtered.length" :show-page-size="width>650" :simple="width<650" :page-size-options="[10,20,50]" /></footer>
        </section>
      </main>
      <ReportSummaryPanel v-if="!narrow" :record="selected" :suites="suites" :disabled="error||loading" @report="record=>emit('report',record)" @detail="id=>emit('detail',id)" />
    </div>
    <a-drawer v-if="narrow" v-model:visible="drawer" title="报告详情" :width="Math.min(440,width-16)" :footer="false"><ReportSummaryPanel :record="selected" :suites="suites" :disabled="error||loading" @report="record=>emit('report',record)" @detail="id=>emit('detail',id)" /></a-drawer>
  </section>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useWindowSize} from '@vueuse/core'
import {IconLayers,IconPlayArrow,IconCheck,IconClose,IconExclamation,IconClockCircle,IconSearch,IconRefresh,IconDownload,IconFile,IconBarChart,IconMore} from '@arco-design/web-vue/es/icon'
import type {AppExecution,AppTestSuite} from '../../types'
import {executionCode,executionState,clockDuration,reportAvailable,reportStatus,reportRate,rateText,reportName,reportSuite,sourceLabel,reportTime,reportInDates,reportOverview,reportCsv} from './reportPresentation'
import ReportSummaryPanel from './ReportSummaryPanel.vue'
import '../test-cases/test-cases-reference.css'
import './reports-reference.css'
const props=defineProps<{projectId:number;executions:AppExecution[];suites:AppTestSuite[];loading:boolean;error:boolean;focusId?:number}>()
const emit=defineEmits<{refresh:[];suites:[];suite:[id:number];report:[record:AppExecution];detail:[id:number]}>()
const {width}=useWindowSize(),narrow=computed(()=>width.value<1400),drawer=ref(false),search=ref(''),source=ref(''),status=ref(''),dates=ref<string[]|undefined>([]),current=ref(1),pageSize=ref(10),selectedId=ref<number|null>(null),selectedKeys=ref<(number|string)[]>([])
const stats=computed(()=>reportOverview(props.executions)),sourceOptions=computed(()=>[...new Set(props.executions.map(record=>record.trigger_mode||''))].filter(Boolean))
const filtered=computed(()=>props.executions.filter(record=>{if(status.value&&executionState(record)!==status.value)return false;if(source.value&&record.trigger_mode!==source.value)return false;if(!reportInDates(record,dates.value))return false;const keyword=search.value.trim().toLowerCase();return !keyword||[executionCode(record),record.id,record.task_id,record.case_name,reportSuite(record,props.suites),record.error_message].join(' ').toLowerCase().includes(keyword)}).sort((a,b)=>(reportTime(b)||0)-(reportTime(a)||0)||b.id-a.id))
const pageRecords=computed(()=>filtered.value.slice((current.value-1)*pageSize.value,current.value*pageSize.value)),selected=computed(()=>filtered.value.find(record=>record.id===selectedId.value)||filtered.value[0]||null)
const select=(record:AppExecution)=>{selectedId.value=record.id;if(narrow.value)drawer.value=true}
const stateOptions=[{value:'passed',label:'通过'},{value:'failed',label:'失败'},{value:'error',label:'异常'},{value:'stopped',label:'已停止'},{value:'running',label:'运行中'},{value:'pending',label:'等待执行'},{value:'completed',label:'已完成 · 未记录结果'}]
const metrics=computed(()=>{const s=stats.value;return [{label:'报告总数',value:s.reports,note:'已结束且可查看报告',tone:'teal',icon:IconLayers},{label:'执行次数',value:s.total,note:'含运行中及等待执行',tone:'teal',icon:IconPlayArrow},{label:'通过次数',value:s.passed,note:'按执行结论统计',tone:'teal',icon:IconCheck},{label:'失败次数',value:s.failed,note:'测试验证失败',tone:'red',icon:IconClose},{label:'异常次数',value:s.error,note:'服务明确标记异常',tone:'orange',icon:IconExclamation},{label:'平均执行时长',value:s.average===null?'—':s.average<3600?clockDuration(s.average).slice(3):String(Math.floor(s.average/3600))+'h'+Math.floor(s.average%3600/60)+'m',note:'按已结束且有耗时记录统计',tone:'purple',icon:IconClockCircle}]})
const distribution=computed(()=>[{label:'通过',value:stats.value.passed,color:'#16a34a'},{label:'失败',value:stats.value.failed,color:'#dc2626'},{label:'异常',value:stats.value.error,color:'#f59e0b'},{label:'其他',value:stats.value.other,color:'#cbd5e1'}])
const donut=computed(()=>{if(!stats.value.total)return '#e8edf3';let start=0;return 'conic-gradient('+distribution.value.map(item=>{const end=start+item.value/stats.value.total*100,segment=`${item.color} ${start}% ${end}%`;start=end;return segment}).join(',')+')'})
const latestRate=computed(()=>[...stats.value.days].reverse().find(day=>day.rate!==null)?.rate??null)
const segments=computed(()=>{const output:string[]=[],parts:string[]=[];stats.value.days.forEach((day,index)=>{if(day.rate===null){if(parts.length)output.push(parts.join(' '));parts.length=0}else parts.push(`${48+index*62},${142-day.rate*1.1}`)});if(parts.length)output.push(parts.join(' '));return output})
const trendDescription=computed(()=>stats.value.days.map(day=>`${day.day} ${rateText(day.rate)}`).join('，'))
const formatTime=(record:AppExecution)=>Number.isFinite(reportTime(record))?new Date(reportTime(record)).toLocaleString('zh-CN',{hour12:false}):'—'
const reset=()=>{search.value='';source.value='';status.value='';dates.value=[];current.value=1}
const exportRows=(records:AppExecution[])=>{if(props.loading||props.error||!records.length)return;const url=URL.createObjectURL(new Blob([reportCsv(records,props.suites)],{type:'text/csv;charset=utf-8;'})),link=document.createElement('a');link.href=url;link.download=`FeiCe-执行报告摘要-项目${props.projectId}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
watch([search,source,status,dates,pageSize],()=>{current.value=1})
watch(filtered,records=>{current.value=Math.min(current.value,Math.max(1,Math.ceil(records.length/pageSize.value)));const ids=new Set(records.map(record=>record.id));selectedKeys.value=selectedKeys.value.filter(id=>ids.has(Number(id)))})
watch(()=>props.focusId,id=>{if(id)selectedId.value=id})
watch(()=>props.projectId,()=>{selectedId.value=null;selectedKeys.value=[];drawer.value=false;reset()})
</script>
